The weights give distances in kilometres.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,2.4);
\coordinate (B) at (3.2,2.4);
\coordinate (C) at (0,0);
\coordinate (D) at (3.2,0);
\draw (A) -- (B) node[midway,above] {$19$};
\draw (A) -- (C) node[midway,left] {$31$};
\draw (B) -- (C) node[midway,sloped,fill=white,inner sep=1pt] {$43$};
\draw (B) -- (D) node[midway,right] {$56$};
\draw (C) -- (D) node[midway,below] {$67$};
\fill (A) circle (2.5pt);
\node[above left] at (A) {$A$};
\fill (B) circle (2.5pt);
\node[above right] at (B) {$B$};
\fill (C) circle (2.5pt);
\node[below left] at (C) {$C$};
